  if (v) {
    var vs = v.currentSrc || v.getAttribute('src') || '';
    if (!vs) { var so = v.querySelector ? v.querySelector('source[src]') : null; if(so) vs = so.getAttribute('src'); }
    if (ok(vs)) return { url: abs(vs), kind: 'video' };
