  if (tag==='SOURCE') { var ssrc = el.getAttribute('src'); if(ok(ssrc)) return { url: abs(ssrc), kind: 'video' }; }
  // 사진
  var img = (tag==='IMG') ? el : (el.querySelector ? el.querySelector('img') : null);
