import { useEffect, useRef, useState } from 'react'

// AI 소셜 패널 — 두 하위 뷰를 하나로 묶는다.
// ① 이미지 만들어 올리기: 생성 서비스(Genspark/ChatGPT/직접 URL)로 이미지를 만들고, 캡션을 확인한 뒤
//    SNS(인스타/유튜브/틱톡)에 올린다. 진행 단계(생성→확인→게시)를 카드로 보여준다.
// ② 관심 블로그 댓글·좋아요: 관심사에 맞는 블로그를 찾아 댓글/좋아요를 남긴다(초안 또는 실제 실행).
//    시작 전 "허용될 사이트"(engageBuildTask 가 넓게 잡아 돌려준 목록)를 사용자가 보고 좁힐 수 있게 하며,
//    활동 기록(중복 방지 근거)을 항상 볼 수 있게 한다.
// 실행은 기존 backend API(social*/engage*/ptask*)만 쓴다 — 이 라운드에서 새 IPC 는 만들지 않는다.

// ===== 백엔드(chrome.ts) 타입을 이 파일에 필요한 만큼만 미러링 — 프리로드 독립 원칙과 동일하게,
// 렌더러 쪽도 각 컴포넌트가 자신이 쓰는 모양만 로컬로 선언한다(AiTab.tsx 의 TaskSummary/RunSummary 와 동일 관례). =====
=== onSaveCaption wiring ===
105:  w, candidates, previewData, captionDraft,
107:  onRetryCaption, onSaveCaption, onResolvePublish,
112:  captionDraft: string
119:  onRetryCaption: () => void
120:  onSaveCaption: (caption: string) => void
185:          <textarea className="ai-input" rows={3} value={captionDraft} placeholder="캡션"
198:              <button className="ai-mini-btn" onClick={onRetryCaption} disabled={!!w.captionPending}
200:              <button className="ai-mini-btn" onClick={() => onSaveCaption(captionDraft)} disabled={!captionDraft.trim()}
204:          <button className="ai-send ai-social-cta" onClick={() => onApprove(captionDraft)} disabled={!captionDraft.trim()}>
287:  const [captionDrafts, setCaptionDrafts] = useState<Record<string, string>>({})
501:                  captionDraft={captionDrafts[w.id] ?? ''}
508:                  onRetryCaption={() => retryCaption(w.id)}
509:                  onSaveCaption={(caption) => saveCaption(w.id, caption)}

