  freshGrant()
  created.length = 0; navigations.length = 0; pendingNav = null
  setTab('tab-1', 'about:blank')
  genWorkspaceId = '(없음)'                   // 어느 세션이었는지 알 수 없다
  genState = 'running'
  const k0 = W3.startImagePost(paramsWin)
  tabState.get('tab-1').gone = true
